import { siteConfig } from "@/config/site.config";

/**
 * Default Open Graph image, generated by src/app/opengraph-image.tsx. Pages must list it
 * explicitly: their `openGraph` replaces the root segment's one, including the image that
 * the file convention adds there (Next merges metadata shallowly).
 */
export const ogImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name}. ${siteConfig.tagline}.`,
  type: "image/png",
} as const;
